ALTER TABLE tenants ADD COLUMN IF NOT EXISTS timezone text NOT NULL DEFAULT 'America/Sao_Paulo';
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS address text NOT NULL DEFAULT '';
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS phone text NOT NULL DEFAULT '';
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS cancellation_minutes integer NOT NULL DEFAULT 60 CHECK(cancellation_minutes BETWEEN 0 AND 10080);
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS reminder_minutes integer NOT NULL DEFAULT 120 CHECK(reminder_minutes BETWEEN 15 AND 10080);
ALTER TABLE professionals ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE professionals ADD COLUMN IF NOT EXISTS commission_kind text NOT NULL DEFAULT 'percent' CHECK(commission_kind IN ('percent','fixed'));
ALTER TABLE professionals ADD COLUMN IF NOT EXISTS commission_fixed integer NOT NULL DEFAULT 0 CHECK(commission_fixed>=0);
ALTER TABLE services ADD COLUMN IF NOT EXISTS active boolean NOT NULL DEFAULT true;
ALTER TABLE services ADD COLUMN IF NOT EXISTS commission_bps integer CHECK(commission_bps BETWEEN 0 AND 10000);
CREATE TABLE IF NOT EXISTS professional_services(professional_id text NOT NULL,service_id text NOT NULL,tenant_id text NOT NULL,enabled boolean NOT NULL DEFAULT true,price integer CHECK(price>=0),duration integer CHECK(duration BETWEEN 5 AND 480),commission_bps integer CHECK(commission_bps BETWEEN 0 AND 10000),PRIMARY KEY(professional_id,service_id),FOREIGN KEY(professional_id,tenant_id) REFERENCES professionals(id,tenant_id),FOREIGN KEY(service_id,tenant_id) REFERENCES services(id,tenant_id));
CREATE TABLE IF NOT EXISTS memberships(user_id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants,role text NOT NULL CHECK(role IN ('owner','receptionist','barber')),professional_id text,active boolean NOT NULL DEFAULT true,FOREIGN KEY(professional_id,tenant_id) REFERENCES professionals(id,tenant_id),CHECK(role<>'barber' OR professional_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS working_schedules(tenant_id text NOT NULL,professional_id text NOT NULL,weekday integer NOT NULL CHECK(weekday BETWEEN 0 AND 6),enabled boolean NOT NULL DEFAULT true,start_minute integer NOT NULL DEFAULT 540,end_minute integer NOT NULL DEFAULT 1080,break_start integer,break_end integer,PRIMARY KEY(professional_id,weekday),FOREIGN KEY(professional_id,tenant_id) REFERENCES professionals(id,tenant_id),CHECK(start_minute>=0 AND end_minute<=1440 AND start_minute<end_minute),CHECK((break_start IS NULL AND break_end IS NULL) OR (break_start>=start_minute AND break_end<=end_minute AND break_end>break_start)));
INSERT INTO working_schedules(tenant_id,professional_id,weekday) SELECT tenant_id,id,d FROM professionals CROSS JOIN generate_series(0,6) d ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS time_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL,professional_id text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,reason text NOT NULL CHECK(length(reason)>0),created_at timestamptz NOT NULL DEFAULT now(),active boolean NOT NULL DEFAULT true,FOREIGN KEY(professional_id,tenant_id) REFERENCES professionals(id,tenant_id),CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS resource_slots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL,professional_id text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,appointment_id uuid UNIQUE REFERENCES appointments(id) ON DELETE CASCADE,block_id uuid UNIQUE REFERENCES time_blocks(id) ON DELETE CASCADE,FOREIGN KEY(professional_id,tenant_id) REFERENCES professionals(id,tenant_id),CHECK(ends_at>starts_at),CHECK((appointment_id IS NOT NULL)::int+(block_id IS NOT NULL)::int=1),CONSTRAINT resource_no_overlap EXCLUDE USING gist(professional_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&));
INSERT INTO resource_slots(tenant_id,professional_id,starts_at,ends_at,appointment_id) SELECT tenant_id,professional_id,starts_at,ends_at,id FROM appointments WHERE status IN ('scheduled','confirmed','in_progress','completed') ON CONFLICT(appointment_id) DO NOTHING;
CREATE OR REPLACE FUNCTION sync_appointment_slot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.status IN ('scheduled','confirmed','in_progress','completed') THEN
 INSERT INTO resource_slots(tenant_id,professional_id,starts_at,ends_at,appointment_id) VALUES(NEW.tenant_id,NEW.professional_id,NEW.starts_at,NEW.ends_at,NEW.id) ON CONFLICT(appointment_id) DO UPDATE SET professional_id=excluded.professional_id,starts_at=excluded.starts_at,ends_at=excluded.ends_at;
 ELSE DELETE FROM resource_slots WHERE appointment_id=NEW.id; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS appointment_resource ON appointments;
CREATE TRIGGER appointment_resource AFTER INSERT OR UPDATE OF professional_id,starts_at,ends_at,status ON appointments FOR EACH ROW EXECUTE FUNCTION sync_appointment_slot();
CREATE OR REPLACE FUNCTION sync_block_slot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.active THEN INSERT INTO resource_slots(tenant_id,professional_id,starts_at,ends_at,block_id) VALUES(NEW.tenant_id,NEW.professional_id,NEW.starts_at,NEW.ends_at,NEW.id) ON CONFLICT(block_id) DO UPDATE SET starts_at=excluded.starts_at,ends_at=excluded.ends_at;
 ELSE DELETE FROM resource_slots WHERE block_id=NEW.id; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS block_resource ON time_blocks;
CREATE TRIGGER block_resource AFTER INSERT OR UPDATE ON time_blocks FOR EACH ROW EXECUTE FUNCTION sync_block_slot();
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS list_price integer;
UPDATE appointments SET list_price=price WHERE list_price IS NULL;
ALTER TABLE appointments ALTER COLUMN list_price SET NOT NULL;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS discount integer NOT NULL DEFAULT 0 CHECK(discount>=0);
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS service_name_snapshot text;
UPDATE appointments a SET service_name_snapshot=s.name FROM services s WHERE s.id=a.service_id AND a.service_name_snapshot IS NULL;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS commission_kind text NOT NULL DEFAULT 'percent';
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS commission_fixed integer NOT NULL DEFAULT 0;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS schedule_version integer NOT NULL DEFAULT 0;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS manage_cipher text;
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS manage_expires_at timestamptz;
UPDATE appointments SET manage_expires_at=starts_at+interval '30 days' WHERE manage_expires_at IS NULL;
CREATE TABLE IF NOT EXISTS cash_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL REFERENCES tenants,opening integer NOT NULL CHECK(opening>=0),opened_at timestamptz NOT NULL DEFAULT now(),opened_by text NOT NULL,closed_at timestamptz,closed_by text,counted integer CHECK(counted>=0),expected integer,difference integer,note text NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS one_open_cash ON cash_sessions(tenant_id) WHERE closed_at IS NULL;
CREATE TABLE IF NOT EXISTS cash_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL REFERENCES tenants,session_id uuid NOT NULL REFERENCES cash_sessions,amount integer NOT NULL,kind text NOT NULL,reference_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,kind,reference_id));
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL REFERENCES tenants,appointment_id uuid NOT NULL REFERENCES appointments,kind text NOT NULL CHECK(kind IN ('receipt','refund')),service_amount integer NOT NULL CHECK(service_amount>=0),tip integer NOT NULL DEFAULT 0 CHECK(tip>=0),fee integer NOT NULL DEFAULT 0 CHECK(fee>=0),method text NOT NULL CHECK(method IN ('Pix','Dinheiro','Cartão')),original_id uuid REFERENCES payments,reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),created_by text NOT NULL,CHECK(service_amount+tip>0),CHECK((kind='receipt' AND original_id IS NULL) OR (kind='refund' AND original_id IS NOT NULL)));
INSERT INTO payments(tenant_id,appointment_id,kind,service_amount,method,created_at,created_by) SELECT tenant_id,id,'receipt',paid,COALESCE(payment_method,'Pix'),starts_at,'legacy-seed' FROM appointments WHERE paid>0 AND NOT EXISTS(SELECT 1 FROM payments p WHERE p.appointment_id=appointments.id);
ALTER TABLE expenses ADD COLUMN IF NOT EXISTS method text NOT NULL DEFAULT 'Pix';
ALTER TABLE payouts ADD COLUMN IF NOT EXISTS method text NOT NULL DEFAULT 'Pix';
CREATE TABLE IF NOT EXISTS advances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL,professional_id text NOT NULL,amount integer NOT NULL CHECK(amount>0),method text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(professional_id,tenant_id) REFERENCES professionals(id,tenant_id));
CREATE TABLE IF NOT EXISTS request_records(tenant_id text NOT NULL,idempotency_key uuid NOT NULL,payload_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY,window_start timestamptz NOT NULL,count integer NOT NULL);
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS version integer NOT NULL DEFAULT 0;
ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_appointment_id_kind_key;
CREATE UNIQUE INDEX IF NOT EXISTS notification_version ON notifications(appointment_id,kind,version);
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS lease_token uuid;
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS lease_until timestamptz;
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS provider_message_id text UNIQUE;
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS last_error text;
ALTER TABLE notifications ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS webhook_events(id text PRIMARY KEY,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tv_devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id text NOT NULL REFERENCES tenants,name text NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',revoked_at timestamptz,last_seen timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS appointments_tenant_start ON appointments(tenant_id,starts_at);
CREATE INDEX IF NOT EXISTS payments_tenant_appointment ON payments(tenant_id,appointment_id);
CREATE INDEX IF NOT EXISTS notifications_due ON notifications(status,due_at);
